{"path":"src/search/filterUsers.js","content":"// Filters the user list by username / full_name (case-insensitive).
// An empty or whitespace-only query returns the list unchanged.
export function filterUsersByQuery(allUsers, query) {
  const searchTerm = query.trim().toLowerCase();
  return searchTerm
    ? (allUsers || []).filter((u) => {
        const uname = (u.username || "").toLowerCase();
        const fname = (u.full_name || "").toLowerCase();
        return uname.includes(searchTerm) || fname.includes(searchTerm);
      })
    : allUsers || [];
}
"}

